#include <bits/stdc++.h>
using namespace std;
using ll = long long;

void solve(){
    ll n; cin >> n;
    vector<ll> arr(3*n);
    for(int i = 0; i < 3*n; i++){
        cin >> arr[i];
    }
    sort(arr.begin(), arr.end(), greater<ll>());
    vector<ll> pref(3*n+1, 0);
    
    for(int i = 0; i < 3*n; i++){
        pref[i+1] = pref[i] + arr[i];
    }
    
    auto sum = [&](int l, int r) -> ll{
        return pref[r] - pref[l];
    };
    
    auto value = [&](int A, int B) -> ll{
        int C = n-A-B;
        int p1 = A;
        int p2 = A + 2 *B;
        int p3 = p2 + 3*C;
        
        ll ans = 0;
        
        ans += 6LL * sum(0, p1);
        ans += 4LL * sum(p1, p2);
        ans += 3LL * sum(p2, p3);
        return ans;
    };
    
    ll answer = 0;
    
    for(int A = 0; A <=n; A++){
        int lo = 0;
        int hi = n-A;
        
        while(lo < hi){
            int mid = (lo + hi)/2;
            ll current = value(A, mid);
            ll next = value(A, mid + 1);
            if(next >= current){
                lo=mid+1;
            }else{
                hi = mid;
            }
        }
        answer = max(answer, value(A, lo));
    }
    
    cout << answer << '\n';
    
    
    
    
    // ll maximum = max(6*arr[0], 4*arr[0]+4*arr[1], 3*arr[0]+3*arr[1]+3*arr[2]);
}

int main() {
	// your code goes here
	ios ::sync_with_stdio(false);
	cin.tie(nullptr);
	
	int t;
	cin >> t;
	while(t--) solve();
	return 0;

}
